 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # Full-length uniform lines are the separators between panels.
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]
    # The separator color is shared by the full lines.
    divider = grid[sep_rows[0]][0] if sep_rows else (grid[0][sep_cols[0]] if sep_cols else None)
    row_bounds = [-1] + sep_rows + [h]
    col_bounds = [-1] + sep_cols + [w]
    row_panels = [(row_bounds[i] + 1, row_bounds[i + 1]) for i in range(len(row_bounds) - 1)]
    col_panels = [(col_bounds[i] + 1, col_bounds[i + 1]) for i in range(len(col_bounds) - 1)]
    colors = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != divider:
                colors[grid[r][c]] = colors.get(grid[r][c], 0) + 1
    background = max(colors, key=colors.get)
    marker = next((color for color in colors if color != background), None)
    out = [[2 for _ in col_panels] for _ in row_panels]
    for ri, (r0, r1) in enumerate(row_panels):
        for ci, (c0, c1) in enumerate(col_panels):
            counts = {}
            for r in range(r0, r1):
                for c in range(c0, c1):
                    if grid[r][c] == marker:
                        counts[c] = counts.get(c, 0) + 1
            if any(n >= 2 for n in counts.values()):
                out[ri][ci] = 1
    return out

